/* FinVaultDB demo seed data: 25 rows per application table. */
USE [FinVaultDB];
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;
GO
/* Constraints are temporarily disabled to support circular foreign-key relationships during seeding. */
EXEC sp_MSforeachtable 'ALTER TABLE ? NOCHECK CONSTRAINT ALL';
GO
